data.jsonataExpression:
/* Frankfurter: the European Central Bank's reference rates, no key needed. These are the currencies it covers. */
(
    $covered := ["AUD","BRL","CAD","CHF","CNY","CZK","DKK","EUR","GBP","HKD","HUF","IDR","ILS","INR","ISK","JPY","KRW","MXN","MYR","NOK","NZD","PHP","PLN","RON","SEK","SGD","THB","TRY","USD","ZAR"];
    $from := $uppercase(from);
    $to := $filter($map([to], $uppercase), function($code) {$code != $from});
    $unknown := $filter([$from, $to], function($code) {$not($code in $covered)});
    $count($unknown) > 0
        ? $error("The European Central Bank publishes no rate for " & $join($unknown, ", ") & ". It covers " & $join($covered, ", ") & ".")
        : $count($to) = 0
            ? $error("Name a different currency to convert to.")
            : {
                "url": "https://api.frankfurter.dev/v1/latest?amount=" & $string(amount) & "&base=" & $from & "&symbols=" & $join($to, ","),
                "dataType": "json"
            }
)
